<script lang="ts">
 import {onMount} from 'svelte';
 import {Button} from '@hasbai/ui/button';
 import {Input} from '@hasbai/ui/input';
 import {Notice} from '@hasbai/ui/notice';
 import * as Dialog from '@hasbai/ui/dialog';
 import {Plus, Pencil, Trash2, KeyRound, RefreshCw} from '@lucide/svelte';
 import type {Api} from './lib';
 type Provider={id:string;name:string;slug:string;base_url:string;description?:string;enable?:boolean};
 type Key={id:string;provider_slug:string;alias:string;default_config:boolean};
 let {api}:{api:Api}=$props();
 let providers=$state<Provider[]>([]),keys=$state<Key[]>([]),gateways=$state<{id:string}[]>([]),gateway=$state('default'),page=$state(1),keyPage=$state(1);
 let loading=$state(true),busy=$state(false),error=$state(''),status=$state('');
 let editing=$state(false),providerId=$state(''),name=$state(''),slug=$state(''),base=$state(''),description=$state(''),enabled=$state(true);
 let keyDialog=$state(false),keyId=$state(''),providerSlug=$state(''),alias=$state('default'),secret=$state(''),defaultKey=$state(true);
 let remove=$state<{path:string;name:string}|null>(null);
 onMount(()=>{void load();});
 async function load(){loading=true;error='';try{const [p,g,k]=await Promise.all([api('/api/admin/providers?page='+page),api('/api/admin/gateways'),api('/api/admin/gateways/'+gateway+'/keys?page='+keyPage)]);providers=((await p.json()) as {result:Provider[]}).result??[];gateways=((await g.json()) as {result:{id:string}[]}).result??[];keys=((await k.json()) as {result:Key[]}).result??[];}catch(e){error=(e as Error).message;}finally{loading=false;}}
 function edit(p?:Provider){providerId=p?.id??'';name=p?.name??'';slug=p?.slug??'';base=p?.base_url??'';description=p?.description??'';enabled=p?.enable??true;editing=true;}
 function editKey(k?:Key){keyId=k?.id??'';providerSlug=k?.provider_slug??'';alias=k?.alias??'default';defaultKey=k?.default_config??true;secret='';keyDialog=true;}
 async function mutate(path:string,method:string,value?:unknown){busy=true;error='';status='';try{await api('/api/admin/'+path,method,value);status='已保存';return true;}catch(e){error=(e as Error).message;return false;}finally{busy=false;}}
 async function saveProvider(){if(await mutate('providers'+(providerId?'/'+providerId:''),providerId?'PATCH':'POST',{name,slug,base_url:base,description,enable:enabled})){editing=false;await load();}}
 async function saveKey(){const value=secret;secret='';if(await mutate('gateways/'+gateway+'/keys'+(keyId?'/'+keyId:''),keyId?'PUT':'POST',keyId?{secret:value}:{provider_slug:providerSlug,alias,default_config:defaultKey,secret:value})){keyDialog=false;await load();}}
 async function deleteItem(){if(remove && await mutate(remove.path,'DELETE')){remove=null;await load();}}
</script>
{#if error}<Notice variant="error">{error}<Button variant="outline" disabled={loading||busy} onclick={load}>重试</Button></Notice>{/if}{#if status}<p role="status">{status}</p>{/if}
<section class="panel"><header class="panel-heading"><div><h2>自定义 Provider</h2><p>管理此 Cloudflare 账号的上游服务。</p></div><Button disabled={busy||loading} onclick={()=>edit()}><Plus size={16}/>添加 Provider</Button></header>
{#if loading}<p role="status">正在加载…</p>{:else if !providers.length}<p class="empty-list">尚未添加自定义 Provider</p>{:else}<div class="records">{#each providers as p(p.id)}<article><div><h3>{p.name}<span class="pill">{p.enable?'已启用':'已停用'}</span></h3><code>custom-{p.slug}</code><p>{p.base_url}</p></div><div class="record-actions"><Button variant="ghost" aria-label={'编辑 '+p.name} disabled={busy} onclick={()=>edit(p)}><Pencil size={16}/></Button><Button variant="ghost" aria-label={'删除 '+p.name} disabled={busy} onclick={()=>remove={path:'providers/'+p.id,name:p.name}}><Trash2 size={16}/></Button></div></article>{/each}</div>{/if}
<div class="pagination"><Button variant="outline" disabled={page===1||loading||busy} onclick={()=>{page--;void load();}}>上一页</Button><span>第 {page} 页</span><Button variant="outline" disabled={providers.length<100||loading||busy} onclick={()=>{page++;void load();}}>下一页</Button></div></section>
<section class="panel"><header class="panel-heading"><div><h2>Provider 密钥 · BYOK</h2><p>密钥保存在 Cloudflare，保存后不可读取。</p></div><div class="key-toolbar"><label><span class="sr-only">选择 Gateway</span><select bind:value={gateway} disabled={busy||loading} onchange={()=>{keyPage=1;void load();}}>{#each gateways as g}<option value={g.id}>{g.id}</option>{/each}</select></label><Button disabled={busy||loading} onclick={()=>editKey()}><KeyRound size={16}/>添加密钥</Button></div></header>
{#if !loading && !keys.length}<p class="empty-list">此 Gateway 尚未配置密钥</p>{:else}<div class="records">{#each keys as k(k.id)}<article><div><h3>{k.provider_slug}<span class="pill">{k.alias}</span>{#if k.default_config}<span class="pill">默认</span>{/if}</h3><p>密钥已存储</p></div><div class="record-actions"><Button variant="outline" disabled={busy} onclick={()=>editKey(k)}><RefreshCw size={14}/>轮换</Button><Button variant="ghost" aria-label={'删除密钥 '+k.provider_slug+' '+k.alias} disabled={busy} onclick={()=>remove={path:'gateways/'+gateway+'/keys/'+k.id,name:k.provider_slug+' / '+k.alias}}><Trash2 size={16}/></Button></div></article>{/each}</div>{/if}
<div class="pagination"><Button variant="outline" disabled={keyPage===1||loading||busy} onclick={()=>{keyPage--;void load();}}>上一页</Button><span>第 {keyPage} 页</span><Button variant="outline" disabled={keys.length<100||loading||busy} onclick={()=>{keyPage++;void load();}}>下一页</Button></div></section>
<Dialog.Root bind:open={editing}><Dialog.Content><Dialog.Header><Dialog.Title>{providerId?'编辑':'添加'} Provider</Dialog.Title><Dialog.Description>配置上游名称和 HTTPS 地址。</Dialog.Description></Dialog.Header><form class="config-form" onsubmit={e=>{e.preventDefault();void saveProvider();}}><label for="provider-name">名称</label><Input id="provider-name" bind:value={name} required/><label for="provider-slug">Slug</label><Input id="provider-slug" bind:value={slug} pattern="[a-zA-Z0-9_-]+" required/><label for="provider-base">Base URL</label><Input id="provider-base" bind:value={base} type="url" placeholder="https://api.example.com" required/><label for="provider-description">说明</label><Input id="provider-description" bind:value={description}/><label class="checkbox"><input type="checkbox" bind:checked={enabled}/>启用 Provider</label>{#if error}<Notice variant="error">{error}</Notice>{/if}<Button type="submit" disabled={busy}>{busy?'保存中…':'保存'}</Button></form></Dialog.Content></Dialog.Root>
<Dialog.Root bind:open={keyDialog} onOpenChange={open=>{if(!open)secret='';}}><Dialog.Content><Dialog.Header><Dialog.Title>{keyId?'轮换':'添加'}密钥</Dialog.Title><Dialog.Description>Gateway：{gateway}。密钥只在保存时发送给 Cloudflare。</Dialog.Description></Dialog.Header><form class="config-form" onsubmit={e=>{e.preventDefault();void saveKey();}}>{#if !keyId}<label for="key-provider">Provider slug</label><Input id="key-provider" bind:value={providerSlug} placeholder="openai 或 custom-codex" required/><label for="key-alias">Alias</label><Input id="key-alias" bind:value={alias} required/><label class="checkbox"><input type="checkbox" bind:checked={defaultKey}/>设为此 Provider 的默认密钥</label>{/if}<label for="key-secret">API Key</label><Input id="key-secret" type="password" autocomplete="new-password" bind:value={secret} required/>{#if error}<Notice variant="error">{error}</Notice>{/if}<Button type="submit" disabled={busy||!secret}>{busy?'保存中…':'保存密钥'}</Button></form></Dialog.Content></Dialog.Root>
<Dialog.Root open={remove!==null} onOpenChange={open=>{if(!open&&!busy)remove=null;}}><Dialog.Content><Dialog.Header><Dialog.Title>删除 {remove?.name}？</Dialog.Title><Dialog.Description>依赖此配置的 AI 请求可能失败。删除后需要重新配置。</Dialog.Description></Dialog.Header><Dialog.Footer><Button variant="outline" disabled={busy} onclick={()=>remove=null}>取消</Button><Button variant="destructive" disabled={busy} onclick={deleteItem}>删除</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
